/* ==========================================
   ATTENDANCE MANAGEMENT COMPONENT
   ========================================== */
const normAtt = (r) => ({
  date: fmtDate(r.date || r.createdAt),
  status: r.status || "Present",
  checkIn: fmtTime(r.checkIn ?? r.checkInTime ?? r.clockIn),
  checkOut: fmtTime(r.checkOut ?? r.checkOutTime ?? r.clockOut),
});

function Attendance() {
  const { user } = useAuth();
  const key = attKey(user);
  const myId = user?.id || user?._id;
  const [logs, setLogs] = useState(() => store.get(key) || []);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");
  const today = new Date().toLocaleDateString();
  const todayLog = logs.find((l) => l.date === today);
  const checkedIn = !!todayLog && todayLog.checkIn !== "--" && todayLog.checkOut === "--";
  const done = !!todayLog && todayLog.checkIn !== "--" && todayLog.checkOut !== "--";

  // Merge server records (if the route exists) with local ones.
  const loadLogs = useCallback(async () => {
    try {
      const raw = toList(await api("/attendance"));
      const mine = raw.filter((r) => {
        const rid = r.employee?._id || r.employee?.id || r.employee || r.user?._id || r.user || r.userId || r.employeeId;
        return !myId || !rid || typeof rid !== "string" || rid === myId;
      });
      const server = mine.map(normAtt);
      const local = store.get(key) || [];
      const merged = [...server, ...local.filter((l) => !server.some((s) => s.date === l.date))];
      store.set(key, merged);
      setLogs(merged);
    } catch {
      /* no server route -> local only */
    }
  }, [key, myId]);

  useEffect(() => {
    loadLogs();
  }, [loadLogs]);

  const upsertToday = (patch) => {
    const cur = store.get(key) || [];
    const has = cur.some((l) => l.date === today);
    const next = has
      ? cur.map((l) => (l.date === today ? { ...l, ...patch } : l))
      : [{ date: today, status: "Present", checkIn: "--", checkOut: "--", ...patch }, ...cur];
    store.set(key, next);
    setLogs(next);
  };

  const run = async (attempts, patch) => {
    setBusy(true);
    setMsg("");
    try {
      try {
        await tryApis(attempts);
      } catch (err) {
        // route missing -> keep working locally; any other error is shown
        if (![404, 405].includes(err.status)) throw err;
      }
      upsertToday(patch);
      await loadLogs();
    } catch (err) {
      setMsg(err.message || "Action failed");
    } finally {
      setBusy(false);
    }
  };

  const handleCheckIn = () =>
    run(
      [
        ["/attendance/checkin", { method: "POST", body: {} }],
        ["/attendance/check-in", { method: "POST", body: {} }],
        ["/attendance/clock-in", { method: "POST", body: {} }],
        ["/attendance", { method: "POST", body: { status: "Present", checkIn: new Date().toISOString() } }],
      ],
      { checkIn: new Date().toLocaleTimeString() }
    );

  const handleCheckOut = () =>
    run(
      [
        ["/attendance/checkout", { method: "POST", body: {} }],
        ["/attendance/check-out", { method: "POST", body: {} }],
        ["/attendance/clock-out", { method: "POST", body: {} }],
        ["/attendance/checkout", { method: "PUT", body: {} }],
        ["/attendance/check-out", { method: "PUT", body: {} }],
      ],
      { checkOut: new Date().toLocaleTimeString() }
    );

  return (
    <div className="page-container">
      <header className="page-header">
        <h1>Attendance Tracking</h1>
        <p>Log your daily working hours and review time history.</p>
      </header>

      <div className="card-box flex-between flex-align">
        <div>
          <h3>Today's Shift Status</h3>
          <p>
            {checkedIn
              ? `Checked in at ${todayLog.checkIn}`
              : done
              ? "Shift completed for today."
              : "You haven't checked in yet today."}
          </p>
          {msg && <div className="error-alert">{msg}</div>}
        </div>
        <div>
          {!todayLog && (
            <button className="btn-success" onClick={handleCheckIn} disabled={busy}>
              <CheckCircle size={18} /> {busy ? "Please wait..." : "Clock In Now"}
            </button>
          )}
          {checkedIn && (
            <button className="btn-warning" onClick={handleCheckOut} disabled={busy}>
              <Clock size={18} /> {busy ? "Please wait..." : "Clock Out"}
            </button>
          )}
        </div>
      </div>

      <div className="section-title mt-6">
        <h3>Attendance Logs</h3>
      </div>

      <div className="table-wrapper">
        <table className="data-table">
          <thead>
            <tr>
              <th>Date</th>
              <th>Status</th>
              <th>Check In Time</th>
              <th>Check Out Time</th>
            </tr>
          </thead>
          <tbody>
            {logs.length === 0 ? (
              <tr><td colSpan="4" className="text-center">No attendance recorded yet.</td></tr>
            ) : (
              logs.map((log, i) => (
                <tr key={i}>
                  <td>{log.date}</td>
                  <td><span className="badge badge-success">{log.status}</span></td>
                  <td>{log.checkIn}</td>
                  <td>{log.checkOut}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ==========================================
   LEAVES MANAGEMENT COMPONENT
   ========================================== */
const EMPTY_LEAVE = { reason: "", startDate: "", endDate: "", type: "Casual" };

// Tries the common route styles and both "Approved" / "approved" spellings.
async function updateLeaveStatus(id, status) {
  const routes = [
    ["PUT", `/leaves/${id}`],
    ["PATCH", `/leaves/${id}`],
    ["PUT", `/leaves/${id}/status`],
    ["PATCH", `/leaves/${id}/status`],
  ];
  let lastErr;
  for (const value of [status, status.toLowerCase()]) {
    for (const [method, path] of routes) {
      try {
        return await api(path, { method, body: { status: value } });
      } catch (err) {
        lastErr = err;
        if ([404, 405].includes(err.status)) continue;
        if (err.status === 400 || err.status === 422) break;
        throw err;
      }
    }
  }
  throw lastErr;
}

function Leaves() {
  const { user } = useAuth();
  const admin = isAdmin(user);
  const [leaves, setLeaves] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState(EMPTY_LEAVE);
  const [saving, setSaving] = useState(false);
  const [loadError, setLoadError] = useState("");

  const fetchLeaves = useCallback(async () => {
    try {
      setLeaves(toList(await api("/leaves")));
      setLoadError("");
    } catch (err) {
      setLoadError(err.message || "Could not load leaves");
    }
  }, []);

  useEffect(() => {
    fetchLeaves();
  }, [fetchLeaves]);

  const handleApplyLeave = async (e) => {
    e.preventDefault();
    if (form.endDate < form.startDate) return alert("End date cannot be before start date.");
    setSaving(true);
    const base = {
      type: form.type,
      leaveType: form.type,
      reason: form.reason,
      startDate: form.startDate,
      endDate: form.endDate,
      from: form.startDate,
      to: form.endDate,
    };
    // 1st try: clean body (backend reads user from token). 2nd try: with name + status.
    const bodies = [base, { ...base, employee: user?.name, status: "Pending" }];
    let lastErr = null;
    let ok = false;
    for (const body of bodies) {
      try {
        await api("/leaves", { method: "POST", body });
        ok = true;
        break;
      } catch (err) {
        lastErr = err;
        if (!err.status || err.status === 401 || err.status === 403) break;
      }
    }
    setSaving(false);
    if (ok) {
      setShowModal(false);
      setForm(EMPTY_LEAVE);
      fetchLeaves();
    } else {
      alert(lastErr?.message || "Failed to apply leave");
    }
  };

  const handleStatusChange = async (id, status) => {
    if (!id) return alert("Leave id not found.");
    try {
      await updateLeaveStatus(id, status);
      fetchLeaves();
    } catch (err) {
      alert(err.message || "Status update failed");
    }
  };

  return (
    <div className="page-container">
      <header className="page-header flex-between">
        <div>
          <h1>Leave Management</h1>
          <p>Apply for leaves and track request approvals.</p>
        </div>
        <button className="btn-primary" onClick={() => setShowModal(true)}>
          <Plus size={18} /> Apply Leave
        </button>
      </header>

      {loadError && <div className="error-alert">{loadError}</div>}

      <div className="table-wrapper">
        <table className="data-table">
          <thead>
            <tr>
              {admin && <th>Employee</th>}
              <th>Type</th>
              <th>Reason</th>
              <th>Dates</th>
              <th>Status</th>
              {admin && <th>Approve / Reject</th>}
            </tr>
          </thead>
          <tbody>
            {leaves.length === 0 ? (
              <tr><td colSpan="6" className="text-center">No leave requests found.</td></tr>
            ) : (
              leaves.map((l, i) => (
                <tr key={getId(l) || i}>
                  {admin && <td>{nameOf(l.employee || l.user)}</td>}
                  <td className="font-medium">{l.type || l.leaveType || "Casual"}</td>
                  <td>{l.reason}</td>
                  <td>{fmtDate(l.startDate || l.from)} to {fmtDate(l.endDate || l.to)}</td>
                  <td><span className={`badge badge-${norm(l.status)}`}>{l.status || "Pending"}</span></td>
                  {admin && (
                    <td>
                      {(norm(l.status) === "pending" || !l.status) && (
                        <div className="flex-align gap-2">
                          <button className="btn-success-sm" onClick={() => handleStatusChange(getId(l), "Approved")}>
                            <Check size={16} />
                          </button>
                          <button className="btn-danger-sm" onClick={() => handleStatusChange(getId(l), "Rejected")}>
                            <X size={16} />
                          </button>
                        </div>
                      )}
                    </td>
                  )}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h3>Apply for Leave</h3>
              <button className="close-btn" onClick={() => setShowModal(false)}><X size={20} /></button>
            </div>
            <form onSubmit={handleApplyLeave}>
              <div className="form-group">
                <label>Leave Type</label>
                <select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}>
                  <option value="Casual">Casual Leave</option>
                  <option value="Sick">Sick Leave</option>
                  <option value="Annual">Annual Leave</option>
                  <option value="Unpaid">Unpaid Leave</option>
                </select>
              </div>
              <div className="form-group">
                <label>Start Date</label>
                <input type="date" required value={form.startDate} onChange={(e) => setForm({ ...form, startDate: e.target.value })} />
              </div>
              <div className="form-group">
                <label>End Date</label>
                <input type="date" required min={form.startDate} value={form.endDate} onChange={(e) => setForm({ ...form, endDate: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Reason</label>
                <textarea required rows="3" value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} placeholder="Reason for leave..." />
              </div>
              <div className="modal-actions">
                <button type="button" className="btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" className="btn-primary" disabled={saving}>{saving ? "Submitting..." : "Submit Application"}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

